<?php
$pend = (int)val("SELECT COUNT(*) FROM deliveries WHERE status='pending'");
$crit = (int)val("SELECT COUNT(*) FROM deliveries dl JOIN relief_missions m ON m.id=dl.mission_id WHERE dl.status='pending' AND m.priority='critical'");
$vt = (int)val("SELECT COUNT(*) FROM deliveries WHERE status='verified' AND DATE(reviewed_at)=CURDATE()");
$rt = (int)val("SELECT COUNT(*) FROM deliveries WHERE status='rejected' AND DATE(reviewed_at)=CURDATE()");
$v30 = (int)val("SELECT COUNT(*) FROM deliveries WHERE status='verified' AND reviewed_at >= NOW() - INTERVAL 30 DAY"); $r30 = (int)val("SELECT COUNT(*) FROM deliveries WHERE status='rejected' AND reviewed_at >= NOW() - INTERVAL 30 DAY");
$queue = rows("SELECT dl.*, m.code, m.title, m.priority, m.coord_confirmed, n.organization, z.name zone, z.lat zlat, z.lng zlng, (SELECT COUNT(*) FROM delivery_photos p WHERE p.delivery_id=dl.id) photos FROM deliveries dl JOIN relief_missions m ON m.id=dl.mission_id LEFT JOIN users n ON n.id=m.ngo_id LEFT JOIN zones z ON z.id=m.zone_id WHERE dl.status='pending' ORDER BY FIELD(m.priority,'critical','high','medium','low'), dl.created_at LIMIT 5");
$hist = rows("SELECT dl.*, m.code, m.title, n.organization FROM deliveries dl JOIN relief_missions m ON m.id=dl.mission_id LEFT JOIN users n ON n.id=m.ngo_id WHERE dl.status<>'pending' ORDER BY dl.reviewed_at DESC LIMIT 5");
dash_head('Audit Dashboard', 'index', 'Independent verification of relief deliveries');
if ($pend): ?><div class="alert amber"><span><b><?= $pend ?> deliver<?= $pend > 1 ? 'ies' : 'y' ?> awaiting verification</b><?php if ($crit): ?><span class="sub">Priority: <?= $crit ?> critical mission<?= $crit > 1 ? 's' : '' ?> should be verified within 4 hours.</span><?php endif; ?></span><a class="btn btn-outline btn-sm" href="<?= url('dashboard/deliveries.php') ?>">Review now</a></div><?php endif; ?>
<div class="kpis"><?= kpi('amber', 'Pending Verification', $pend, "$crit critical priority", 'clock', 'a') . kpi('green', 'Verified Today', $vt, 'Since midnight', 'check', 'g') . kpi('red', 'Rejected Today', $rt, 'Evidence mismatch', 'x', 'r') . kpi('blue', 'Verification Rate', ($v30 + $r30 ? round($v30 / ($v30 + $r30) * 100) : 100) . '%', 'Last 30 days', 'chart', 'b') ?></div>
<section class="panel"><header><div><h2>Pending Verification Queue</h2><span class="sub">Sorted by priority, oldest first</span></div><a class="btn btn-outline btn-sm" href="<?= url('dashboard/deliveries.php') ?>">View all</a></header>
<?php foreach ($queue as $d): $dist = ($d['gps_lat'] !== null && $d['zlat'] !== null) ? haversine((float)$d['gps_lat'], (float)$d['gps_lng'], (float)$d['zlat'], (float)$d['zlng']) : null; ?>
  <a class="list-row" href="<?= url('dashboard/review.php?id=' . (int)$d['id']) ?>" style="color:var(--ink);text-decoration:none"><span><code><?= e($d['code']) ?></code> <?= badge($d['priority']) ?><br><b><?= e($d['organization']) ?>: <?= e(ucfirst($d['title'])) ?></b><small><?= e($d['zone']) ?> · <?= number_format($d['recipients']) ?> families · <?= e(dt_label($d['created_at'])) ?></small></span>
  <span class="chips"><span class="ev <?= $d['photos'] >= 3 ? 'ok' : 'bad' ?>"><?= icon('camera') ?><?= (int)$d['photos'] ?></span><span class="ev <?= $dist !== null && $dist <= EVIDENCE_RADIUS_KM ? 'ok' : 'bad' ?>"><?= icon('pin') ?>GPS</span><span class="ev <?= $d['coord_confirmed'] ? 'ok' : 'bad' ?>">Sig</span></span></a>
<?php endforeach; if (!$queue): ?><div class="empty">The queue is clear. Nothing is waiting for verification.</div><?php endif; ?></section>
<section class="panel"><header><h2>Recent Audit History</h2><a href="<?= url('dashboard/history.php') ?>" style="font-size:13px">Full history →</a></header>
<?php foreach ($hist as $d): ?><div class="list-row"><span><code><?= e($d['code']) ?></code><br><b><?= e($d['organization']) ?>: <?= e($d['title']) ?></b><small><?= e(dt_label($d['reviewed_at'])) ?></small></span><?= badge($d['status']) ?></div><?php endforeach; if (!$hist) echo '<div class="empty">No reviews yet.</div>'; ?></section>
<?php dash_foot();
